```go
package main

import (
	"embed"
	"net/http"

	"github.com/gin-gonic/gin"
)

//go:embed static/dist
var staticFiles embed.FS

func main() {
	r := gin.Default()
	r.StaticFS("/", http.FS(staticFiles))
	r.Run("127.0.0.1:8081")
